INSERT INTO [Categories] ([Id], [Name], [Slug], [Description], [ImageUrl], [Icon], [SortOrder], [IsActive], [ParentCategoryId], [CreatedAt]) VALUES (48, N'Hoa Chơi Tết & Nụ Tầm Xuân', N'hoa-choi-tet-nu-tam-xuan', N'Nụ tầm xuân, hoa đào, hoa mai, chậu hoa lan chưng Tết', N'https://cdn.s99.vn/ss1/prod/product/f9c8789deaa72623b02897ad162235d4.jpg', NULL, 1, 1, NULL, N'2026-08-11 11:32:03.840');
INSERT INTO [Categories] ([Id], [Name], [Slug], [Description], [ImageUrl], [Icon], [SortOrder], [IsActive], [ParentCategoryId], [CreatedAt]) VALUES (49, N'Dịch Vụ Trang Trí Hoa Sự Kiện', N'dich-vu-trang-tri-hoa-su-kien', N'Nhận thiết kế trang trí hoa tươi hội nghị, tiệc gala, sinh nhật lớn', N'https://png.pngtree.com/png-clipart/20220311/ourlarge/pngtree-micro-three-dimensional-metal-plant-flower-plum-blossom-frame-png-image_4415785.png', NULL, 2, 1, NULL, N'2026-08-11 11:32:03.840');
INSERT INTO [Categories] ([Id], [Name], [Slug], [Description], [ImageUrl], [Icon], [SortOrder], [IsActive], [ParentCategoryId], [CreatedAt]) VALUES (50, N'Gói Đăng Ký Hoa Định Kỳ', N'goi-dang-ky-hoa-dinh-ky', N'Giao hoa tươi định kỳ hàng tuần cho văn phòng, khách sạn, căn hộ', N'https://via.placeholder.com/300x300?text=Hoa+Dinh+Ky', N'fa-sync-alt', 3, 1, NULL, N'2026-08-11 11:32:03.840');
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (1, N'Hoa Hồng Đỏ Ecuador', N'hoa-hong-do-ecuador', N'Bó hoa hồng đỏ Ecuador cao cấp nhập khẩu trực tiếp từ Nam Mỹ, nổi bật với đường kính bông lớn từ 8-10cm, cánh hoa dày dặn, mịn như nhung và độ bền tươi kéo dài từ 7-10 ngày. Sản phẩm được thiết kế theo phong cách hiện đại với giấy gói tone đen xám sang trọng, thắt nơ ruy-băng tinh tế. Phù hợp làm quà tặng cao cấp dịp Valentine 14/2, kỷ niệm ngày cưới, sinh nhật người yêu hoặc tỏ tình lãng mạn.', N'Tình yêu mãnh liệt, nồng cháy và sự tôn trọng sâu sắc.', 850000.00, 780000.00, 1, 24, N'Hoa Hồng Ecuador', N'Đỏ', 49, 1, 120, N'https://www.hoathangba.com/wp-content/uploads/2026/03/z7606431731449_72b83ba359c635fe01758e2a2c0ee082.jpg', N'2026-08-11 11:32:22.943', N'2026-08-14 06:43:22.111', N'Vừa', N'Valentine, Sinh Nhật', NULL);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (2, N'Hoa Hồng Kem Dâu', N'hoa-hong-kem-dau', N'Bó hoa tươi kết hợp những bông hoa hồng kem dâu nhẹ nhàng cùng lá bạc (Eucalyptus) đốm tròn nhập khẩu. Sự xen kẽ giữa màu pastel dịu mát và màu xanh xám của lá tạo nên tổng thể thanh lịch, ngọt ngào. Sản phẩm được bọc bằng giấy bọc mờ Hàn Quốc màu kem trang nhã. Đây là lựa chọn lý tưởng dành tặng bạn gái, đồng nghiệp nữ, bạn thân nhân ngày sinh nhật hoặc dịp 8/3, 20/10.', N'Sự ngọt ngào, tinh tế và lời cám ơn chân thành.', 450000.00, 390000.00, 1, 11, N'Hoa Hồng Kem Dâu', N'Hồng Kem', 39, 1, 85, N'https://siinstore.com/wp-content/uploads/2025/10/bo-hoa-hong-kem-dau-1.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Sinh Nhật Bạn Gái', 0.8);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (3, N'Hoa Hồng Juliet Cam', N'hoa-hong-juliet-cam', N'Bó hoa kiệt tác từ giống hoa hồng triệu đô David Austin Juliet với sắc cam thạch anh kiêu sa, xếp cánh dạng xoáy cổ điển cực kỳ quyến rũ. Kết hợp nhẹ nhàng cùng hoa baby trắng và lá đuôi phụng. Bó hoa mang hơi thở hoàng gia Châu Âu, rất thích hợp tặng sếp nữ, đối tác quan trọng, hoặc làm hoa cầm tay cô dâu trong ngày lễ trọng đại.', N'Sự quý phái, tình yêu hoàn hảo và sự gắn kết.', 950000.00, 890000.00, 1, 24, N'Hoa Hồng Juliet', N'Cam Thạch Anh', 30, 1, 60, N'https://i.pinimg.com/736x/84/9f/b7/849fb79d837027698dfbdb1659282c9b.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Lớn', N'Kỷ Niệm, Tỏ Tình', 1.2);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (4, N'Hoa Hồng Phấn Ohara', N'hoa-hong-phan-ohara', N'Bó hoa hồng Ohara màu hồng phấn nhập khẩu từ Ecuador, nổi tiếng với tầng cánh xoáy phức tạp và hương thơm trái cây tự nhiên nồng nàn. Bó hoa được phối cùng cúc tana trắng nhỏ nhắn và lá ngạn tươi. Hương thơm dịu nhẹ tỏa ngát không gian, thích hợp làm quà tặng bất ngờ cho phái đẹp trong các dịp lễ đặc biệt hoặc ngày kỷ niệm.', N'Vẻ đẹp e ấp, dịu dàng và nét đẹp kiêu kỳ.', 720000.00, 720000.00, 0, 24, N'Hoa Hồng Ohara', N'Hồng Phấn', 35, 1, 45, N'https://hoavily.com/uploads/file/bai%20viet%20hoa/bo-hoa-hong-tuoi-ohara-cuc-xinh(1).jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Sinh Nhật, 8/3', 0.9);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (5, N'Hoa Hồng Trắng Spirit', N'hoa-hong-trang-spirit', N'Bó hoa hồng trắng Spirit thuần khiết kết hợp cùng cành lá đô la xanh tươi và nơ lụa satin trắng. Thiết kế tối giản nhưng toát lên vẻ sang trọng, thanh thoát. Rất thích hợp làm hoa bó cầm tay cô dâu, quà tặng sinh nhật bạn bè thích sự giản dị, hoặc gửi tặng trong các buổi lễ tốt nghiệp, sự kiện trang trọng.', N'Sự thuần khiết, chân thành và lời hứa vĩnh cửu.', 550000.00, 490000.00, 1, 18, N'Hoa Hồng Trắng', N'Trắng', 45, 1, 95, N'https://www.hoahongsi.com/Upload/cate/trangco-9794_600x600.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Hoa Cưới, Sinh Nhật', 0.8);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (6, N'Hoa Hướng Dương Đà Lạt', N'hoa-huong-duong-da-lat', N'Bó hoa gồm 10 bông hướng dương bông to rạng rỡ thu hoạch từ trang trại Đà Lạt, phối cùng hoa thạch thảo tím và lá cau cảnh. Tông màu vàng rực rỡ kết hợp sắc tím mộng mơ mang đến năng lượng tích cực, niềm vui tràn đầy. Đây là món quà tặng kinh điển dành cho tân sinh viên ngày tốt nghiệp, chúc mừng đồng nghiệp thăng chức hoặc tặng thầy cô giáo 20/11.', N'Sự kiên trì, niềm tin và tương lai xán lạn.', 380000.00, 350000.00, 1, 25, N'Hướng Dương', N'Vàng', 60, 1, 210, N'https://7fgarden.com/wp-content/uploads/2024/04/bo-hoa-huong-duong-20-bong-e1742920056887-600x697.webp', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Tốt Nghiệp, Sinh Nhật', 0.9);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (7, N'Lẵng Hoa Hướng Dương Phối Hồng Vàng', N'lang-hoa-huong-duong-phoi-hong-vang', N'Lẵng hoa gỗ để bàn kết hợp giữa 5 bông hướng dương vàng tươi, hoa hồng vàng chùa, hoa đồng tiền cam và cúc calimero xanh. Lẵng hoa được cắm tròn xoe, đặn dặn, phối thêm nơ đỏ may mắn. Thích hợp trưng bày tại quầy lễ tân, bàn làm việc, hoặc làm quà tặng mừng lễ khai trương cửa hàng, chúc mừng sinh nhật sếp và đối tác kinh doanh.', N'Chúc thành công rực rỡ và sự nghiệp thăng tiến.', 650000.00, 590000.00, 1, 13, N'Hướng Dương, Hồng Vàng', N'Vàng, Cam', 25, 1, 75, N'https://i.pinimg.com/736x/1c/c7/f7/1cc7f7e5f36f00c71a2870337f8161d8.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Lớn', N'Sinh Nhật Sếp, Khai Trương', 1.5);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (8, N'Lan Hồ Điệp Vàng Hoàng Kim', N'lan-ho-diep-vang-hoang-kim', N'Chậu lan hồ điệp 5 cành hoa màu vàng hoàng kim rực rỡ, cánh hoa to dày, xếp hàng đều đặn. Hoa được trồng trong chậu sứ trắng trạm khắc hoa văn cổ điển, phủ gốc bằng rêu xanh và gắn thêm nơ vải đỏ trang trọng. Cây có khả năng giữ hoa tươi từ 1 đến 2 tháng nếu tưới nước đúng cách. Sản phẩm là món quà phong thủy hàng đầu dịp Tết Nguyên Đán, mừng tân gia, mừng khai trương doanh nghiệp.', N'Tài lộc, thịnh vượng và sự trường tồn.', 1650000.00, 1500000.00, 1, 26, N'Lan Hồ Điệp', N'Vàng', 15, 1, 30, N'https://cdn.hstatic.net/products/200001026522/3452_dab7cf830b3915e88fb7d746d95ee1f6_7a649df3731141feb1947110dbda3486_bd059f40ea8a43e7bc0f89567287918e_master.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Lớn', N'Khai Trương, Tết', 3.5);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (9, N'Lan Hồ Điệp Trắng Tinh Khôi', N'lan-ho-diep-trang-tinh-khoi', N'Chậu lan hồ điệp trắng gồm 3 cành uốn nghệ thuật mềm mại, nhị hoa màu vàng nhạt thanh nhã. Chậu cây bằng gốm Bát Tràng cao cấp màu trắng đồng bộ, trang trí tiểu cảnh tuyết sơn và cành may mắn. Phù hợp đặt trang trí phòng khách sang trọng, sảnh khách sạn, văn phòng tổng giám đốc hoặc quà tặng mừng thọ, quà biếu người lớn tuổi.', N'Sự thanh cao, quý phái và tinh tế.', 1100000.00, 1100000.00, 0, 26, N'Lan Hồ Điệp', N'Trắng', 20, 1, 40, N'https://i.pinimg.com/736x/2d/b9/ef/2db9ef07ef2ff16b77c415e986f01abc.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Tân Gia, Khai Trương', 2.8);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (10, N'Lan Hồ Điệp Tím Đột Biến', N'lan-ho-diep-tim-dot-bien', N'Chậu lan hồ điệp 5 cành sở hữu sắc tím đột biến với các mảng chớp trắng nghệ thuật trên từng cánh hoa. Chậu sứ vân đá hiện đại kết hợp phụ kiện trang trí dây treo may mắn. Dòng lan hiếm có độ bền cao, đại diện cho tình cảm gắn kết bền chặt. Món quà hoàn hảo biểu thị sự trân trọng gửi tới Mẹ, vợ, hoặc các khách hàng VIP.', N'Sự quý phái, thủy chung và đẳng cấp.', 1800000.00, 1680000.00, 1, 26, N'Lan Hồ Điệp', N'Tím', 10, 1, 18, N'https://i.pinimg.com/originals/ec/bf/bd/ecbfbdb1b5766e2431b913b4f1ed63b1.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Lớn', N'Tặng Mẹ, Sự Kiện', 3.8);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (11, N'Hoa Tulip Trắng Hà Lan', N'hoa-tulip-trang-ha-lan', N'Bó hoa gồm 15 bông Tulip trắng tinh khôi nhập khẩu nguyên cành từ Hà Lan, thân cây mập mạp, lá xanh mướt. Bó hoa cắm dáng dài tự nhiên, gói giấy kiếng trong suốt phối ruy-băng vải thô phong cách Minimalism (Tối giản). Thích hợp làm hoa cưới cầm tay cô dâu, tặng người yêu thích phong cách Châu Âu hiện đại hoặc chúc mừng dịp kỷ niệm ngày quen nhau.', N'Tình yêu thuần khiết, chân thành và lời hứa hẹn.', 880000.00, 820000.00, 1, 29, N'Hoa Tulip', N'Trắng', 25, 1, 65, N'https://i.pinimg.com/736x/76/e1/a2/76e1a2f42f91637a58ec92aa8289f02b.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Hoa Cưới, Valentine', 0.7);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (12, N'Hoa Tulip Hồng Pastel', N'hoa-tulip-hong-pastel', N'Bó 10 bông Tulip nhập khẩu sắc hồng pastel nhẹ nhàng như ánh mây ban sáng. Thân hoa uốn lượn tự nhiên, bó cùng lá ngạn và bọc giấy lụa Hàn Quốc màu hồng phấn. Món quà mang lại cảm giác dễ chịu, nữ tính, cực kỳ được ưa chuộng để làm quà tặng sinh nhật bạn gái, quà tặng 8/3 hoặc chụp ảnh concept nghệ thuật.', N'Sự chăm sóc, quan tâm và tình yêu nhẹ nhàng.', 850000.00, 850000.00, 0, 29, N'Hoa Tulip', N'Hồng Pastel', 30, 1, 80, N'https://i.pinimg.com/736x/f8/d1/c1/f8d1c1a5b805e1de3b4e324325b6f7ec.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Sinh Nhật Bạn Gái, 8/3', 0.7);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (13, N'Hoa Tulip Vàng', N'hoa-tulip-vang', N'Bó hoa gồm 12 bông Tulip vàng tươi rói gợi liên tưởng đến ánh nắng ấm áp. Thiết kế gói dáng tròn đầy đặn kết hợp giấy gói màu xanh mint thanh mát. Hoa Tulip vàng đại diện cho nụ cười và năng lượng tích cực, là món quà tuyệt vời gửi lời chúc hồi phục sức khỏe, chúc mừng thăng chức hoặc dành tặng bạn bè thân thiết.', N'Nụ cười rạng rỡ và sự may mắn trong cuộc sống.', 820000.00, 780000.00, 1, 29, N'Hoa Tulip', N'Vàng', 20, 1, 45, N'https://7fgarden.com/wp-content/uploads/2024/01/bo-hoa-tulip-vang.webp', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Chúc Mừng, Tốt Nghiệp', 0.7);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (14, N'Hoa Cẩm Tú Cầu Xanh Dương', N'hoa-cam-tu-cau-xanh-duong', N'Bó hoa nổi bật với 3 bông Cẩm Tú Cầu xanh dương kích thước lớn (đường kính 18-20cm/bông) trồng tại Đà Lạt. Phối hợp cùng hoa cúc tana trắng và lá bạc. Tông màu xanh mát mắt mang lại cảm giác bình yên, thư thái. Phù hợp làm quà tặng lời cảm ơn, lời xin lỗi chân thành hoặc chúc mừng kỷ niệm ngày yêu.', N'Sự chân thành, lòng biết ơn và sự cảm thông.', 420000.00, 380000.00, 1, 27, N'Cẩm Tú Cầu', N'Xanh Dương', 40, 1, 110, N'https://i.pinimg.com/736x/eb/86/dc/eb86dc64a07c03a9534e297cc96a57e1.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Kỷ Niệm, Cảm Ơn', 0.9);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (15, N'Hoa Cẩm Tú Cầu Hồng', N'hoa-cam-tu-cau-hong', N'Bó hoa Cẩm Tú Cầu sắc hồng mơ mộng gồm 2 bông lớn bồng bềnh, xen kẽ cành hoa baby trắng mềm mại. Bọc ngoài là lớp giấy lụa hai màu hồng trắng đính nơ thơ mộng. Món quà dễ thương dành riêng cho các cô nàng yêu thích sự lãng mạn, phù hợp tặng dịp sinh nhật, kỷ niệm tháng yêu nhau.', N'Tình yêu chân thành và niềm hạnh phúc trọn vẹn.', 450000.00, 450000.00, 0, 27, N'Cẩm Tú Cầu', N'Hồng', 30, 1, 70, N'https://hoatuoihoamy.com/wp-content/uploads/2021/05/IMG_0418.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Sinh Nhật', 0.9);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (16, N'Hoa Baby Trắng Tuyết', N'hoa-baby-trang-tuyet', N'Bó hoa Baby trắng nhập khẩu khổng lồ, bông hoa nhỏ li ti dầy đặc tạo hình như đám mây tuyết bồng bềnh. Hoa baby nhập khẩu có ưu điểm khô tự nhiên vẫn giữ nguyên hình dáng mà không bị rụng cánh. Bó hoa gói giấy đen đối lập tôn lên sắc trắng nổi bật. Là món quà cực hot dành cho bạn trẻ tỏ tình, tặng sinh nhật hoặc làm đạo cụ chụp ảnh.', N'Tình yêu vĩnh cửu, sự ngây thơ và tinh khiết.', 490000.00, 430000.00, 1, 28, N'Hoa Baby', N'Trắng', 50, 1, 250, N'https://www.hoatuoihoangtran.com/uploads/source/02d5d8d472ccbc92e5dd.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Lớn', N'Sinh Nhật, Tỏ Tình', 0.7);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (17, N'Hoa Baby Hồng Nhuộm', N'hoa-baby-hong-nhuom', N'Bó hoa Baby phun nhuộm màu hồng pastel bằng công nghệ Hà Lan hiện đại, màu sắc lên đều, không phai và giữ được độ tươi lâu. Bó hoa thiết kế tròn trịa gợn sóng, gói giấy mờ màu kem lót lụa hồng. Phù hợp làm quà tặng ngọt ngào dịp Valentine, ngày Quốc tế Phụ nữ 8/3 hoặc quà bất ngờ cho bạn gái.', N'Sự đáng yêu và sự nuông chiều.', 520000.00, 520000.00, 0, 28, N'Hoa Baby', N'Hồng', 35, 1, 140, N'https://7fgarden.com/wp-content/uploads/2024/03/bo-hoa-baby-hong-2_optimized.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Lớn', N'Valentine, Sinh Nhật', 0.8);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (18, N'Hoa Cúc Tana Hà Nội', N'hoa-cuc-tana-ha-noi', N'Bó hoa Cúc Tana tươi mộc mạc với hàng trăm bông hoa nhỏ cánh trắng nhị vàng như những mặt trời tí hon. Hoa mang hương thơm đồng nội nhẹ nhàng, gợi cảm giác bình yên. Bó hoa bọc giấy báo cổ điển Vintage hoặc giấy kraft nâu. Thích hợp tặng bạn bè, người yêu trong những cuộc hẹn hò cà phê cuối tuần hoặc sinh nhật phong cách giản dị.', N'Tình yêu bình dị, sự ngây thơ và chân thành.', 320000.00, 290000.00, 1, 30, N'Cúc Tana', N'Trắng, Vàng', 60, 1, 310, N'https://tse2.mm.bing.net/th/id/OIP.GI7ohEwJLxSt746PolgXdQHaJQ?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Hẹn Hò, Sinh Nhật', 0.6);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (19, N'Hoa Cúc Pingpong Vàng', N'hoa-cuc-pingpong-vang', N'Lẵng hoa để bàn cắm kết hợp giữa cúc Pingpong vàng tròn xoe như quả bóng nhỏ, hoa cát tường xanh và cúc tana. Cấu trúc lẵng cắm bo tròn cẩn thận trong giỏ mây tre đan thiên nhiên. Sự đáng yêu của cúc Pingpong mang đến cảm giác vui vẻ, dễ chịu, rất thích hợp trang trí bàn học, bàn làm việc hoặc làm quà chúc mừng.', N'Sự trọn vẹn, viên mãn và niềm vui tràn đầy.', 450000.00, 420000.00, 1, 5, N'Cúc Pingpong', N'Vàng', 30, 1, 85, N'https://www.hoahongsi.com/Upload/product/ping-pong-9614_600x600.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Sinh Nhật, Cảm Ơn', 1);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (20, N'Hoa Cúc Đại Đóa Vàng', N'hoa-cuc-dai-doa-vang', N'Vòng hoa viếng tang lễ đơm từ hoa Cúc Đại Đóa vàng kết hợp cúc trắng và lá cau cảnh. Vòng hoa thiết kế dạng hình tròn truyền thống thể hiện sự luân hồi và trọn vẹn. Màu sắc trang nghiêm, tươi tắn nhằm gửi lời chia buồn sâu sắc, động viên gia quyến và tiễn đưa người đã khuất về cõi vĩnh hằng.', N'Sự thành kính, tưởng nhớ sâu sắc người quá cố.', 680000.00, 680000.00, 0, 21, N'Cúc Đại Đóa', N'Vàng', 25, 1, 90, N'https://domyflower.vn/wp-content/uploads/2024/06/z5569689547473_9cc3767ee6f249af0db62e6210191e3a.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Lớn', N'Tang Lễ', 3.2);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (21, N'Hoa Cẩm Chướng Hồng', N'hoa-cam-chuong-hong', N'Lẵng hoa cẩm chướng hồng viền dâu mềm mại cắm cùng hoa hồng kem và cành lá đồng tiền. Lẵng nhựa giả mây cao cấp kèm nơ nỉ sang trọng. Hoa Cẩm Chướng Hồng là biểu tượng quốc tế của Ngày Của Mẹ (Mother’s Day), món quà trọn vẹn lòng hiếu thảo gửi tặng Mẹ, Bà hoặc Cô giáo kính yêu.', N'Sự biết ơn vô bờ bến và lòng tình mẫu tử.', 580000.00, 520000.00, 1, 12, N'Cẩm Chướng', N'Hồng', 40, 1, 130, N'https://tse1.explicit.bing.net/th/id/OIP.lu8SoLcNwKt3mTViegJPogHaJ4?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Ngày Của Mẹ, Sinh Nhật', 1.1);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (22, N'Hoa Cát Tường Tím', N'hoa-cat-tuong-tim', N'Bó hoa Cát Tường cánh mỏng màu tím viền trắng mềm mại như dải lụa. Phối cùng hoa thạch thảo trắng và lá bạc đuôi phụng. Cát tường là loài hoa được người Á Đông cực kỳ yêu thích vì tên gọi mang ý nghĩa may mắn, đại cát đại tường. Phù hợp tặng dịp sinh nhật, lễ Quốc tế Phụ nữ 8/3 hoặc kỷ niệm ngày thành lập công ty.', N'Sự may mắn, vạn sự cát tường và bình an.', 420000.00, 390000.00, 1, 36, N'Hoa Cát Tường', N'Tím', 35, 1, 95, N'https://flowersight.com/wp-content/uploads/2024/07/bo-hoa-cat-tuong-tim-3.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Quốc Tế Phụ Nữ 8/3', 0.8);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (23, N'Hoa Cát Tường Xanh', N'hoa-cat-tuong-xanh', N'Bó hoa Cát Tường tông màu xanh lá phối trắng dịu mát, tạo cảm giác tươi mới, tràn đầy sinh khí. Bó hoa bọc giấy lụa xanh mint cao cấp. Thích hợp làm quà tặng bạn bè, đồng nghiệp nam/nữ nhân ngày bắt đầu công việc mới, mừng tốt nghiệp hoặc quà tặng thăm bệnh.', N'Sự hy vọng và những khởi đầu thuận lợi.', 400000.00, 400000.00, 0, 5, N'Hoa Cát Tường', N'Xanh Lá, Trắng', 30, 1, 60, N'https://flowersight.com/wp-content/uploads/2024/07/bo-hoa-cat-tuong-xanh.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Chúc Mừng', 0.8);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (24, N'Hoa Sen Hồng Quan Âm', N'hoa-sen-hong-quan-am', N'Bó hoa Sen Hồng Quan Âm (Sen Bách Diệp) được gấp cánh nghệ thuật tỉ mỉ tỏa lộ phần nhị vàng thơm ngát. Bó hoa kết hợp cùng đài sen xanh, lá sen tươi và bọc ngoài bằng giấy kraft nâu vintage. Sản phẩm mang nét đẹp văn hóa Việt Nam thuần túy, thích hợp làm quà tặng đối tác nước ngoài, tặng người lớn tuổi, đi lễ chùa hoặc sự kiện văn hóa truyền thống.', N'Sự thanh cao, thuần khiết và nét đẹp Việt Nam.', 550000.00, 490000.00, 1, 5, N'Hoa Sen', N'Hồng', 25, 1, 110, N'https://domyflower.vn/wp-content/uploads/2024/08/z5740340151091_b96baf53f4fba96003315229757c3741-scaled.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Lễ Chùa, Kỷ Niệm', 1.2);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (25, N'Hoa Sen Trắng Tinh Khôi', N'hoa-sen-trang-tinh-khoi', N'Bó hoa Sen Trắng nhẹ nhàng, từng bông hoa chụm tròn thuần khiết phối cùng lá sen mát lành và nơ đay thô mộc. Hương thơm nhẹ dịu tỏa ra từ nhị sen mang lại sự thanh tịnh cho không gian. Thích hợp dành tặng những người trân trọng giá trị mộc mạc, tĩnh lặng hoặc trang trí sự kiện thiền định, trà đạo.', N'Sự bình yên trong tâm hồn và sự thanh lịch.', 580000.00, 580000.00, 0, 5, N'Hoa Sen', N'Trắng', 20, 1, 75, N'https://images.squarespace-cdn.com/content/v1/5bf7bf0b506fbeeca9e55208/1653990971896-LYE764FE4F8YPYUV3PJF/HOA+CUOI+HOA+CAM+TAY+HOA+SEN', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Sự Kiện, Tri Ân', 1.2);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (26, N'Hoa Ly Úc Trắng Hương Thơm', N'hoa-ly-uc-trang-huong-thom', N'Bình hoa Ly trắng Úc (Lily) gồm 5 cành tai lớn (mỗi cành 3-4 nụ bông), nở xòe rực rỡ và tỏa hương thơm nồng nàn. Hoa được cắm sẵn trong bình thủy tinh trong suốt cao cấp. Phù hợp trưng bày phòng khách gia đình, bàn ăn dịp Tết Nguyên Đán hoặc quà tặng chúc mừng tân gia nhà mới.', N'Sự kiêu hãnh, đức hạnh và sự trong sạch.', 650000.00, 590000.00, 1, 34, N'Hoa Ly', N'Trắng', 30, 1, 80, N'https://tse1.mm.bing.net/th/id/OIP.jUTMyjxytqioCHpuswpDIQHaJ4?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Trang Trí Nhà, Tết', 1.8);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (27, N'Hoa Thạch Thảo Tím Đà Lạt', N'hoa-thach-thao-tim-da-lat', N'Bó hoa Thạch Thảo tím (hoa Cúc Nhỏ) nở rộ sum sê, sắc tím mộng mơ đặc trưng của núi rừng Đà Lạt. Bó hoa bọc giấy báo phong cách Pháp cổ điển. Thạch Thảo có độ bền tươi cao (trên 7 ngày), là món quà dễ thương, giản dị tặng bạn gái, nam giới hoặc bạn bè học sinh sinh viên.', N'Sự thủy chung, hoài niệm và tình yêu dịu dàng.', 280000.00, 250000.00, 1, 14, N'Thạch Thảo', N'Tím', 50, 1, 180, N'https://tse1.mm.bing.net/th/id/OIP.fllxCj9ULDj-_rkRLOMQeQHaJ4?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Sinh Nhật Nam, Hẹn Hò', 0.6);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (28, N'Hoa Thạch Thảo Trắng', N'hoa-thach-thao-trang', N'Bó hoa Thạch Thảo trắng muốt mỏng mong tựa như tuyết đầu mùa. Cành hoa nhẹ nhàng, dễ phối đồ chụp ảnh dã ngoại. Sản phẩm được bọc bằng giấy lụa đục mịn và thắt dây thừng nhỏ. Món quà mang nét đẹp ngây thơ, mộc mạc dành tặng bạn bè.', N'Sự thanh tú, mỏng mong và thuần khiết.', 280000.00, 280000.00, 0, 5, N'Thạch Thảo', N'Trắng', 40, 1, 120, N'https://tse2.mm.bing.net/th/id/OIP.D_14aNPEyrnQPBs5qac78gHaHa?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Chụp Ảnh, Hẹn Hò', 0.6);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (29, N'Hoa Hồng Sáp Thơm Đỏ', N'hoa-hong-sap-thom-do', N'Bó hoa gồm 19 bông hoa Hồng Sáp thơm màu đỏ nhung làm từ sáp thơm cao cấp, cánh hoa mềm mịn như thật và lưu hương thơm dịu nhẹ lên tới 2-3 năm. Hoa không lo bị héo, giữ nguyên hình dáng lâu dài. Bó hoa bọc giấy nhung đen cao cấp đính nơ đỏ. Phù hợp cho những ai muốn lưu giữ kỷ niệm tình yêu lâu bền.', N'Tình yêu vĩnh cửu không bao giờ phai nhạt.', 350000.00, 299000.00, 1, 39, N'Hoa Sáp', N'Đỏ', 100, 1, 420, N'https://hoagiaynhunxoan.com/wp-content/uploads/2021/03/Bo-hoa-hong-sap-thom-do.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Sinh Nhật, Tỏ Tình', 0.6);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (30, N'Hoa Lavender Khô Pháp', N'hoa-lavender-kho-phap', N'Bó hoa Lavender (Oải Hương) khô nhập khẩu từ vùng Provence nước Pháp. Bó hoa tỏa hương thơm thảo mộc tự nhiên giúp giảm căng thẳng, thư giãn tinh thần và xua đuổi côn trùng. Bó hoa được bọc giấy kraft vintage, thích hợp đặt trang trí phòng ngủ, bàn làm việc hoặc tủ quần áo.', N'Sự may mắn, bình yên và giữ hương lâu bền.', 390000.00, 390000.00, 0, 41, N'Hoa Lavender', N'Tím', 45, 1, 160, N'https://down-vn.img.susercontent.com/file/vn-11134207-7ras8-m0w328jujmof28', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Nhỏ', N'Trang Trí Phòng, Quà Tặng', 0.4);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (31, N'Cây Sen Đá Kim Kim', N'cay-sen-da-kim-kim', N'Chậu tiểu cảnh Sen Đá kết hợp giữa Sen Đá Phật Bà, Sen Đá Nâu và Cẩm Nhung đỏ cắm trong chậu gốm nung mộc mạc. Cây dễ chăm sóc, chịu khô hạn tốt, phù hợp đặt cạnh máy tính để giảm bức xạ điện tử. Quà tặng nhỏ nhắn ý nghĩa cho đồng nghiệp, học sinh.', N'Sức sống dẻo dai, kiên trì vượt qua khó khăn.', 180000.00, 150000.00, 1, 42, N'Sen Đá', N'Xanh Lá', 80, 1, 300, N'https://tse2.mm.bing.net/th/id/OIP.NwpWsxMl3gYE_lkL4RT2jQHaHa?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Nhỏ', N'Trang Trí Bàn Làm Việc', 0.5);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (32, N'Cây Kim Tiền Chiêu Tài', N'cay-kim-tien-chieu-tai', N'Chậu cây Kim Tiền lá xanh mướt sáng bóng, thân cây khỏe khoắn vươn thẳng. Cây trồng trong chậu sứ trắng bo tròn cao 40cm. Cây có khả năng lọc không khí tốt và mang ý nghĩa phong thủy chiêu tài đón lộc. Thích hợp làm quà tặng mừng tân gia, khai trương văn phòng.', N'Thu hút tài lộc, may mắn và vương khí.', 350000.00, 350000.00, 0, 43, N'Cây Phong Thủy', N'Xanh Lá', 50, 1, 190, N'https://tse1.mm.bing.net/th/id/OIP.vadOSvQMr2A2knGEi4UakwHaHa?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Nhỏ', N'Khai Trương, Tân Gia', 1.8);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (33, N'Gấu Bông Teddy 30cm', N'gau-bong-teddy-30cm', N'Chú gấu bông Teddy kích thước 30cm chất liệu lông xoắn cao cấp màu nâu hạt dẻ, đeo nơ đỏ trước ngực. Lông gấu mềm mịn, không rụng, an toàn cho da. Món quà tặng kèm hoàn hảo cùng các bó hoa hồng dịp sinh nhật hoặc Valentine.', N'Gửi gắm sự ấm áp và chiều chuộng.', 180000.00, 150000.00, 1, 44, N'Phụ Kiện', N'Nâu', 100, 1, 280, N'https://images.unsplash.com/photo-1559454403-b8fb88521f11?w=600', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Nhỏ', N'Sinh Nhật', 0.3);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (34, N'Bánh Kem Tươi Dâu Tây', N'banh-kem-tuoi-dau-tay', N'Bánh kem sinh nhật đường kính 18cm cốt bánh gato vani mềm xốp, phủ lớp kem tươi béo ngậy không ngọt gắt và trang trí dâu tây tươi Đà Lạt căng mộng trên bề mặt. Giao hàng kèm nến và dao cắt bánh. Món quà trọn vẹn cho buổi tiệc sinh nhật.', N'Trọn vẹn hương vị ngọt ngào cho bữa tiệc.', 350000.00, 350000.00, 0, 45, N'Bánh Kem', N'Trắng, Đỏ', 25, 1, 95, N'https://i.pinimg.com/originals/0d/d2/f2/0dd2f23678701a4f1c9bbe16c4ff6f8f.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Sinh Nhật', 1);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (35, N'Hộp Socola Bỉ Valentine', N'hop-socola-bi-valentine', N'Hộp Socola nghệ thuật gồm 16 viên với các hương vị đắng ngọt hòa quyện (truffle, matcha, dâu tây). Hộp quà thiết kế hình trái tim bọc vải nhung sang trọng. Món quà lãng mạn không thể thiếu dành tặng người thương dịp Valentine 14/2.', N'Hương vị ngọt ngào sâu đậm của tình yêu.', 260000.00, 230000.00, 1, 46, N'Socola', N'Nâu', 60, 1, 210, N'https://images.unsplash.com/photo-1549007994-cb92caebd54b?w=600', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Nhỏ', N'Valentine', 0.4);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (36, N'Nụ Tầm Xuân Đỏ May Mắn', N'nu-tam-xuan-do-may-man', N'Bình nụ Tầm Xuân nhuộm sắc đỏ may mắn gồm 30 cành dài 1m2 cắm xòe tròn trong bình gốm dát vàng. Các nụ hoa êm ái như lông nốt mọc dầy trên cành. Tầm xuân có độ bền từ 6 tháng đến 1 năm, là vật phẩm trang trí Tết cổ truyền mang lại không khí rộn rã, may mắn.', N'Sự đơm hoa kết trái, may mắn và thịnh vượng.', 850000.00, 790000.00, 1, 48, N'Nụ Tầm Xuân', N'Đỏ', 30, 1, 85, N'https://caycanhviet.vn/wp-content/uploads/2024/01/y-nghia-nu-tam-xuan-2.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Lớn', N'Tết Nguyên Đán', 2.8);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (37, N'Hoa Mẫu Đơn Hồng Nhập Khẩu', N'hoa-mau-don-hong-nhap-khau', N'Bó hoa Mẫu Đơn (Peony) hồng nhập khẩu Hà Lan gồm 5 bông hoa kích thước siêu lớn, cánh hoa mỏng nhẹ xếp lớp kỳ công cùng mùi thơm dịu ngọt. Bó hoa bọc giấy lụa cao cấp. Mẫu đơn là vương hậu của các loài hoa, là quà tặng xa xỉ dành riêng cho dịp đặc biệt.', N'Sự vương giả, phú quý và sắc đẹp tuyệt mỹ.', 1500000.00, 1390000.00, 1, 24, N'Hoa Mẫu Đơn', N'Hồng', 15, 1, 40, N'https://tse4.mm.bing.net/th/id/OIP.RtAjnuXzQ1FSWReRdCN5SAHaHY?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Lớn', N'Kỷ Niệm, Cầu Hôn', 1.3);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (38, N'Hoa Hồng Môn Đỏ Khai Trương', N'hoa-hong-mon-do-khai-truong', N'Kệ hoa mừng khai trương 2 tầng kết hợp hoa Hồng Môn đỏ rực rỡ, hoa hướng dương vàng và hoa lan hồ điệp. Khung kệ gỗ chắc chắn trang trí băng rôn chúc mừng. Thiết kế hoành tráng, màu sắc may mắn thích hợp gửi tặng đối tác dịp khai trương cửa hàng, công ty.', N'Tình cảm nồng thắm và sự nhiệt huyết kinh doanh.', 1200000.00, 1100000.00, 1, 15, N'Hồng Môn, Hướng Dương', N'Đỏ, Vàng', 20, 1, 50, N'https://tse1.mm.bing.net/th/id/OIP.-Zk_RExpfSmQvAEgNhc8RAHaHa?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Khổng Lồ', N'Khai Trương', 4.5);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (39, N'Hoa Cúc Calimero Đa Sắc', N'hoa-cuc-calimero-da-sac', N'Bó hoa Cúc Calimero phối nhiều màu sắc sinh động (tím, xanh, vàng, nâu). Bông cúc nhỏ xinh có độ bền tươi kinh ngạc tới 2 tuần. Bó hoa gói gọn gàng dễ thương, thích hợp tặng học sinh, sinh viên hoặc đặt trang trí góc học tập.', N'Sự nhỏ nhắn, kiên cường và niềm vui nhỏ mỗi ngày.', 250000.00, 220000.00, 1, 30, N'Cúc Calimero', N'Đa Sắc', 70, 1, 190, N'https://sala.emartmall.com.vn/image/cache/catalog/products/8935077359091/8935077359091-600x600.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Nhỏ', N'Tặng Bạn Bè', 0.5);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (40, N'Hoa Hồng Ecuador Nhập Xanh Dương', N'hoa-hong-ecuador-nhap-xanh-duong', N'Bó hoa gồm 10 bông Hồng Ecuador màu xanh dương độc đáo (màu nhuộm nhập khẩu an toàn). Bó hoa mang vẻ đẹp bí ẩn, cuốn hút, gói cùng giấy bọc màu xám ghi hiện đại. Quà tặng ấn tượng dành cho những người có tính cách cá tính, thích sự mới lạ.', N'Sự bí ẩn, ước mơ và điều kỳ diệu.', 950000.00, 950000.00, 0, 24, N'Hoa Hồng Ecuador', N'Xanh Dương', 18, 1, 35, N'https://tse4.mm.bing.net/th/id/OIP.Atrb9uiXezdzg58oHJvdTAHaHa?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Sinh Nhật Nam', 1);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (41, N'Hoa Thiên Nga Trắng Cắm Bình', N'hoa-thien-nga-trang-cam-binh', N'Bình hoa Thiên Nga (Ornithogalum) trắng tinh khôi cắm dáng cao thanh thoát trong bình thủy tinh. Hoa lâu tàn, cành hoa uốn cong tự nhiên nghệ thuật. Phù hợp trang trí không gian nội thất hiện đại, tối giản.', N'Sự tinh tế, thanh thoát cho không gian sống.', 750000.00, 680000.00, 1, 34, N'Hoa Thiên Nga', N'Trắng', 15, 1, 25, N'https://trucvufarm.com.vn/wp-content/uploads/2026/02/z7561713727848_732822216f36764eb9f7ade607820593.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Trang Trí Phòng Khách', 1.5);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (42, N'Hoa Baby Khô Cắm Lọ', N'hoa-baby-kho-cam-lo', N'Lọ hoa Baby khô phối nhiều màu pastel cắm sẵn trong lọ thủy tinh dây đay. Hoa khô giữ màu sắc tươi tắn tới vài năm mà không cần tưới nước. Quà trang trí bàn học, bàn làm việc mộc mạc.', N'Kỷ niệm đong đầy không phai mờ.', 320000.00, 290000.00, 1, 41, N'Hoa Baby Khô', N'Đa Sắc', 50, 1, 140, N'https://tse1.mm.bing.net/th/id/OIP.XtHtZgLymSouML02jlvY5wHaHa?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Nhỏ', N'Trang Trí Bàn', 0.6);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (43, N'Hoa Thu Cúc Vàng Tươi', N'hoa-thu-cuc-vang-tuoi', N'Lẵng hoa Thu Cúc vàng tươi đơm đặn cắm cùng lá quế và nơ đỏ. Loài hoa cúc truyền thống mang lại hương vị ấm cúng, phù hợp làm hoa cúng lễ, dâng hương ngày rằm, mùng một hoặc ngày giỗ tổ tiên.', N'Sự hiếu thảo, trang nghiêm và kính trọng.', 350000.00, 350000.00, 0, 5, N'Thu Cúc', N'Vàng', 40, 1, 100, N'https://i.pinimg.com/736x/a8/03/73/a803732182304a7d483ed5948d05b82a.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Lễ Tế, Kính Hiếu', 1.1);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (44, N'Hoa Cẩm Chướng Đỏ Bó Dài', N'hoa-cam-chuong-do-bo-dai', N'Bó hoa Cẩm Chướng đỏ thắm 20 bông cắm dáng dài kiêu hãnh, bọc giấy kraft nâu. Màu đỏ nồng nàn đại diện cho tình yêu tha thiết và lời tri ân. Phù hợp tặng thầy cô giáo hoặc người lớn tuổi.', N'Tình yêu tha thiết và sự ngưỡng mộ.', 380000.00, 350000.00, 1, 12, N'Cẩm Chướng', N'Đỏ', 30, 1, 80, N'https://kingfruit.net/uploads/file/hoatuoi360-%20%20bo%20hoa%20cam%20chuong%202.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Tri Ân, Sinh Nhật', 0.8);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (45, N'Hoa Đồng Tiền Cam Rực Rỡ', N'hoa-dong-tien-cam-ruc-ro', N'Lẵng hoa Đồng Tiền cam tươi kết hợp cúc calimero và lá phụ. Đồng tiền là loài hoa mang năng lượng vui vẻ, tượng trưng cho tiền tài may mắn. Món quà tân gia hoặc chúc mừng ấm áp.', N'Tiền tài, may mắn và năng lượng tích cực.', 480000.00, 420000.00, 1, 17, N'Đồng Tiền', N'Cam', 35, 1, 115, N'https://ariloflower.com/wp-content/uploads/2025/10/BO-HOA-TOT-NGHIEP-HOA-DONG-TIEN-TONE-DO-CAM-TANG-BAN-NAM-BAN-LINH-VA-RUC-RO-B410-800x1000.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Tân Gia, Khai Trương', 1.2);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (46, N'Hoa Hồng Quế Cổ Hải Phòng', N'hoa-hong-que-co-hai-phong', N'Bó hoa Hồng Quế cổ Hải Phòng bông nhỏ chùm nhiều hoa, màu hồng đậm thơm nồng nàn hương trà cổ điển. Bó hoa mang vẻ đẹp thuần Việt, mộc mạc.', N'Vẻ đẹp truyền thống và sự hoài niệm.', 390000.00, 390000.00, 0, 24, N'Hoa Hồng Cổ', N'Hồng Đỏ', 25, 1, 65, N'https://hoatuoicomay.com/wp-content/uploads/2025/09/z6892297508479_4bb1bca58760d0c3cca02d99b3937238.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Tặng Người Thân', 0.8);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (47, N'Thiệp Chúc Mừng Hoa Cúc Khô', N'thiep-chuc-mung-hoa-cuc-kho', N'Thiệp chúc mừng làm bằng giấy Craft bìa cứng đính hoa cúc khô thật thủ công. Bên trong để trống để bạn tự tay viết những lời chúc đong đầy tình cảm gửi người nhận.', N'Gửi gắm câu chúc viết tay ý nghĩa.', 30000.00, 30000.00, 0, 47, N'Phụ Kiện', N'Nâu Cổ Điển', 200, 1, 450, N'https://www.hummingbirdcards.co.uk/wp-content/uploads/2021/09/LOTS-OF-LOVE-DRIED-FLOWER-CARD-2.jpg', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Nhỏ', N'Kèm Quà Tặng', 0.05);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (48, N'Hoa Thủy Tiên Trắng Ngày Tết', N'hoa-thuy-tien-trang-ngay-tet', N'Bình hoa Thủy Tiên trắng gọt tỉa nghệ thuật, củ hoa ra rễ trắng như râu tiên và nở hoa thơm ngát. Món hoa chơi Tết thanh cao truyền thống của người Hà Nội cổ.', N'Thanh cao, ngũ phúc lâm môn và tài lộc.', 680000.00, 620000.00, 1, 48, N'Thủy Tiên', N'Trắng, Vàng', 15, 1, 35, N'https://tse2.mm.bing.net/th/id/OIP.M0yvlRpXxoV7V9OARMmnaQHaHa?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Tết Nguyên Đán', 1.5);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (49, N'Cây Trầu Bà Cột Phong Thủy', N'cay-trau-ba-cot-phong-thuy', N'Chậu cây Trầu Bà leo cột lá lớn xanh mướt trồng trong chậu sứ cao 80cm. Cây có khả năng hấp thụ độc tố formaldehyde cực tốt, thích hợp làm cây cảnh văn phòng, nhà mới.', N'Sự vươn lên, uy quyền và may mắn.', 380000.00, 350000.00, 1, 43, N'Cây Phong Thủy', N'Xanh Lá', 40, 1, 90, N'https://tse2.mm.bing.net/th/id/OIP.SrINPHwGQesZehZfXqymeQAAAA?r=0&w=342&h=500&rs=1&pid=ImgDetMain&o=7&rm=3', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Văn Phòng, Khai Trương', 2.2);
INSERT INTO [Products] ([Id], [Name], [Slug], [Description], [Meaning], [Price], [SalePrice], [IsOnSale], [CategoryId], [FlowerType], [Color], [Stock], [IsActive], [SoldCount], [MainImageUrl], [CreatedAt], [UpdatedAt], [BouquetSize], [Occasion], [WeightKg]) VALUES (50, N'Gói Đăng Ký Bình Hoa Tươi Tuần', N'goi-dang-ky-binh-hoa-tuoi-tuan', N'Dịch vụ cung cấp bình hoa tươi giao tận nơi thay mới 1 lần/tuần (trọn gói 4 tuần/tháng). Hoa được cắm thay đổi phong cách linh hoạt theo mùa, phù hợp cho văn phòng công ty, sảnh lễ tân hoặc căn hộ cao cấp.', N'Không gian luôn ngập tràn hương sắc hoa thiên nhiên.', 1200000.00, 1200000.00, 0, 50, N'Đa Dạng', N'Đa Sắc', 50, 1, 40, N'https://images.unsplash.com/photo-1508610048659-a06b669e3321?w=600', N'2026-08-11 11:32:22.943', N'2026-08-11 11:32:22.943', N'Vừa', N'Định Kỳ Tuần', 2);
